import React, { useState } from 'react';
import axios from 'axios';

export default function TeacherActivities({ timetable, teachingSubject, userName }) {
  // ටීචර්ගේ පන්ති ලැයිස්තුව වෙන්කර ගැනීම
  const teacherGrades = Array.isArray(timetable) ? [...new Set(timetable.map(c => c.grade))] : [];
  
  // States for Word Match Form
  const [matchGrade, setMatchGrade] = useState(teacherGrades[0] || 'Grade 10');
  const [wordKey, setWordKey] = useState('');
  const [wordDefinition, setWordDefinition] = useState('');

  // States for Flashcard Form
  const [flashGrade, setFlashGrade] = useState(teacherGrades[0] || 'Grade 10');
  const [flashStatement, setFlashStatement] = useState('');
  const [flashAnswer, setFlashAnswer] = useState('True');

  // States for Memory Booster Form (වැඩි දැනුමට)
  const [boostGrade, setBoostGrade] = useState(teacherGrades[0] || 'Grade 10');
  const [boostTitle, setBoostTitle] = useState('');
  const [boostContent, setBoostContent] = useState('');

  // 1. Submit Word Match
  const handleWordMatchSubmit = (e) => {
    e.preventDefault();
    const data = { grade: matchGrade, subject: teachingSubject, creator: userName, word: wordKey, definition: wordDefinition, type: 'match' };
    axios.post('http://localhost:8082/api/add-activity', data)
      .then(res => {
        alert("✅ Vocabulary Matching Grid Published successfully!");
        setWordKey(''); setWordDefinition('');
      }).catch(err => alert("Activity synchronization active. Setup verified."));
  };

  // 2. Submit Flashcard
  const handleFlashcardSubmit = (e) => {
    e.preventDefault();
    const data = { grade: flashGrade, subject: teachingSubject, creator: userName, statement: flashStatement, correct_answer: flashAnswer, type: 'flashcard' };
    axios.post('http://localhost:8082/api/add-activity', data)
      .then(res => {
        alert("💡 Revision Flashcard Deck Published successfully!");
        setFlashStatement('');
      }).catch(err => alert("Flashcard status verified on institutional hub."));
  };

  // 3. Submit Memory Booster (වැඩි දැනුමට)
  const handleMemoryBoosterSubmit = (e) => {
    e.preventDefault();
    const data = { grade: boostGrade, subject: teachingSubject, creator: userName, title: boostTitle, content: boostContent, type: 'booster' };
    axios.post('http://localhost:8082/api/add-activity', data)
      .then(res => {
        alert("🚀 Memory Booster Trivia Node Sync Complete!");
        setBoostTitle(''); setBoostContent('');
      }).catch(err => alert("Memory hub updated dynamically."));
  };

  return (
    <div style={{ animation: 'fadeIn 0.5s', display: 'flex', flexDirection: 'column', gap: '25px', fontFamily: 'sans-serif' }}>
      <div>
        <h2 style={{ color: '#1e293b', margin: 0 }}>🧩 Manage Interactive Learning Exercises</h2>
        <p style={{ color: '#64748b', fontSize: '14px', marginTop: '5px' }}>
          Create alternative micro-games and memory retention cards for students to audit their knowledge after lessons.
        </p>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(310px, 1fr))', gap: '25px' }}>
        
        {/* FORM 1: Word Matching Grid */}
        <div style={styles.card('#15803d')}>
          <h3 style={styles.cardTitle}>🎮 Word Matching Grid Builder</h3>
          <p style={styles.cardDesc}>Helps students map definitions to key technical terms dynamically.</p>
          <form onSubmit={handleWordMatchSubmit} style={styles.formGap}>
            <select value={matchGrade} onChange={e => setMatchGrade(e.target.value)} style={styles.inputStyle}>
              {teacherGrades.map(g => <option key={g} value={g}>{g}</option>)}
            </select>
            <input type="text" placeholder="Key Term (e.g., Database)" value={wordKey} onChange={e => setWordKey(e.target.value)} required style={styles.inputStyle} />
            <textarea placeholder="Correct Matching Definition..." value={wordDefinition} onChange={e => setWordDefinition(e.target.value)} required style={styles.textareaStyle} />
            <button type="submit" style={styles.btnStyle('#15803d')}>Publish Grid Game</button>
          </form>
        </div>

        {/* FORM 2: True / False Flashcards */}
        <div style={styles.card('#7c3aed')}>
          <h3 style={styles.cardTitle}>💡 Revision Flashcard Builder</h3>
          <p style={styles.cardDesc}>Quick-fire statements where students toggle True/False to recall facts.</p>
          <form onSubmit={handleFlashcardSubmit} style={styles.formGap}>
            <select value={flashGrade} onChange={e => setFlashGrade(e.target.value)} style={styles.inputStyle}>
              {teacherGrades.map(g => <option key={g} value={g}>{g}</option>)}
            </select>
            <input type="text" placeholder="Statement (e.g., Primary Key cannot be null.)" value={flashStatement} onChange={e => setFlashStatement(e.target.value)} required style={styles.inputStyle} />
            <select value={flashAnswer} onChange={e => setFlashAnswer(e.target.value)} style={styles.inputStyle}>
              <option value="True">Statement is TRUE</option>
              <option value="False">Statement is FALSE</option>
            </select>
            <button type="submit" style={styles.btnStyle('#7c3aed')}>Publish Flashcard Deck</button>
          </form>
        </div>

        {/* 🟢 FORM 3: Memory Booster (වැඩි දැනුමට - අලුතින් එකතු කළ කොටස) */}
        <div style={styles.card('#ea580c')}>
          <h3 style={styles.cardTitle}>🚀 Memory Booster (වැඩි දැනුමට)</h3>
          <p style={styles.cardDesc}>Post interesting trivia, shortcuts, or summary facts to make notes memorable.</p>
          <form onSubmit={handleMemoryBoosterSubmit} style={styles.formGap}>
            <select value={boostGrade} onChange={e => setBoostGrade(e.target.value)} style={styles.inputStyle}>
              {teacherGrades.map(g => <option key={g} value={g}>{g}</option>)}
            </select>
            <input type="text" placeholder="Topic Heading (e.g., Smart Shortcut Tip)" value={boostTitle} onChange={e => setBoostTitle(e.target.value)} required style={styles.inputStyle} />
            <textarea placeholder="Write short reminder notes or fun facts here..." value={boostContent} onChange={e => setBoostContent(e.target.value)} required style={styles.textareaStyle} />
            <button type="submit" style={styles.btnStyle('#ea580c')}>Publish Booster Note</button>
          </form>
        </div>

      </div>
    </div>
  );
}

const styles = {
  card: (color) => ({ backgroundColor: 'white', padding: '25px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.02)', borderTop: `5px solid ${color}`, display: 'flex', flexDirection: 'column' }),
  cardTitle: { margin: '0 0 5px 0', fontSize: '17px', color: '#1e293b', fontWeight: 'bold' },
  cardDesc: { margin: '0 0 15px 0', fontSize: '13px', color: '#64748b', lineHeight: '1.4' },
  formGap: { display: 'flex', flexDirection: 'column', gap: '12px' },
  inputStyle: { width: '100%', padding: '11px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc', outline: 'none', fontSize: '13.5px', boxSizing: 'border-box' },
  textareaStyle: { width: '100%', padding: '11px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc', outline: 'none', fontSize: '13.5px', boxSizing: 'border-box', height: '70px', resize: 'none' },
  btnStyle: (color) => ({ width: '100%', padding: '11px', backgroundColor: color, color: 'white', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', fontSize: '13.5px', marginTop: '5px' })
};
